220	export function changedSince(worktree, base) {
221	  try {
222	    const tracked = git(worktree, 'diff', '--name-only', base).split('\n');
223	    const untracked = git(worktree, 'ls-files', '--others', '--exclude-standard').split('\n');
224	    return [...new Set([...tracked, ...untracked].map(line => line.trim()).filter(Boolean))];
