228	/**
229	 * What a worktree has changed since a commit, committed or not, new files
230	 * included: [{ path, how: 'added' | 'changed' | 'removed' }], by path. A
231	 * build session with no screens of its own shows it (prelude/build).
232	 */
233	export function filesChangedSince(worktree, base) {
234	  try {
235	    const files = new Map();
236	    for (const line of git(worktree, 'diff', '--name-status', '--no-renames', base).split('\n')) {
237	      const [status, path] = line.trim().split('\t');
238	      if (path) files.set(path, status.startsWith('A') ? 'added' : status.startsWith('D') ? 'removed' : 'changed');
239	    }
240	    for (const path of git(worktree, 'ls-files', '--others', '--exclude-standard').split('\n').map(line => line.trim()).filter(Boolean)) files.set(path, 'added');
241	    return [...files].map(([path, how]) => ({ path, how })).sort((a, b) => a.path.localeCompare(b.path));
242	  } catch { return []; }
243	}
